// Extract incoming message details from Meta WhatsApp Cloud API
const entry = $input.item.json.entry?.[0] || {};
const change = entry.changes?.[0]?.value || {};
const message = change.messages?.[0];

if (!message) {
  return [{ json: { shouldProcess: false } }];
}

const fromPhone = message.from;
let userText = '';
let isInteractive = false;
let interactiveId = '';

if (message.type === 'text') {
  userText = message.text?.body || '';
} else if (message.type === 'interactive') {
  isInteractive = true;
  interactiveId = message.interactive?.button_reply?.id || message.interactive?.list_reply?.id || '';
  userText = message.interactive?.button_reply?.title || message.interactive?.list_reply?.title || interactiveId;
} else if (message.type === 'button') {
  userText = message.button?.text || message.button?.payload || '';
}

return [{
  json: {
    shouldProcess: true,
    fromPhone,
    userText,
    isInteractive,
    interactiveId,
    timestamp: new Date().toISOString(),
    supabaseUrl: 'https://ajnvowztvmtdkpyyklbh.supabase.co',
    supabaseKey: 'sb_publishable_Pi9tMaGnO5269CXhnajIcA_fp3Ch-AO'
  }
}];

const { createClient } = require('@supabase/supabase-js');
const client = createClient('https://ajnvowztvmtdkpyyklbh.supabase.co', 'sb_publishable_Pi9tMaGnO5269CXhnajIcA_fp3Ch-AO');

// Load active timetable tables
const [sRes, bRes, cRes, fRes, rRes, stRes] = await Promise.all([
  client.from('class_sessions').select('*'),
  client.from('batches').select('*'),
  client.from('courses').select('*'),
  client.from('faculty').select('*'),
  client.from('rooms').select('*'),
  client.from('students').select('*')
]);

return JSON.stringify({
  sessions: sRes.data || [],
  batches: bRes.data || [],
  courses: cRes.data || [],
  faculty: fRes.data || [],
  rooms: rRes.data || [],
  students: stRes.data || []
});

